  KEY `ix_graph_relations_source_id` (`source_id`),
  KEY `ix_graph_relations_source_type` (`source_type`)
) ENGINE=InnoDB AUTO_INCREMENT=93928 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


