-- Table: user_ratings
DROP TABLE IF EXISTS `user_ratings`;
CREATE TABLE `user_ratings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `book_id` int NOT NULL,
