  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_book_rating` (`user_id`,`book_id`),
  KEY `ix_user_ratings_user_id` (`user_id`),
  KEY `ix_user_ratings_book_id` (`book_id`),
  CONSTRAINT `user_ratings_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
